-- deprecated: False
-- sha256: 77474ffb4f2f93c38b8baac8a4dd28500b4fcb63a1bfb8a7b49b49dee99fadce
WITH abtest_table AS (
    SELECT 
        user_id,
        CAST(experiment_group_id AS INT) AS abtest_group,
        grass_date,
        grass_region
    FROM 
        livestream.ls_mart_dim_abtest_user_group
    WHERE 
        tz_type = 'local'
        AND grass_date = ${local_date}
        AND grass_region IN (${grass_region})
    GROUP BY user_id,abtest_group,grass_date,grass_region
),

civ_pre_table AS (
    SELECT
        user_id,
        CASE
            WHEN 'home-daily_discover-video' IN (feature_detail, source1_feature_detail, source2_feature_detail) THEN 'video_dd_all'
            WHEN 'home-shopee_video-video_card' IN (feature_detail, source1_feature_detail, source2_feature_detail) THEN 'homepage_video_all'
            ELSE 'another'
        END AS scenario_tag,
        grass_region,
        sum(imp_cnt) AS imp_cnt,
        sum(click_cnt) AS click_cnt
    FROM
        srdi_mart.dwm_sr_data_warehouse_platform_user_item
    WHERE
        local_date = ${local_date}
        AND grass_region IN (${grass_region})
        AND operation IN (${operation})
        AND user_id > 0
    GROUP BY 
        user_id, 
        feature_detail,
        source1_feature_detail,
        source2_feature_detail,
        grass_region
),

civ_table AS (
    SELECT
        user_id,
        scenario_tag,
        grass_region,
        sum(imp_cnt) AS imp_cnt,
        sum(click_cnt) AS click_cnt
    FROM
        civ_pre_table
    GROUP BY user_id, scenario_tag, grass_region
),

joined_data as (
    SELECT
        t1.user_id,
        scenario_tag,
        abtest_group,
        imp_cnt,
        click_cnt
    FROM
        abtest_table t1
        LEFT JOIN civ_table t2
        ON t1.user_id = t2.user_id
            AND t1.grass_region = t2.grass_region
),

final_data as (
    SELECT
        scenario_tag,
        abtest_group,
        sum(imp_cnt) AS card_imp_cnt,
        sum(click_cnt) AS card_click_cnt,
        --count(DISTINCT user_id) AS exp_uu,
        count(DISTINCT IF((imp_cnt >0), user_id, NULL)) AS card_imp_uu,
        count(DISTINCT IF((click_cnt >0), user_id, NULL)) AS card_click_uu
    FROM 
        joined_data
    GROUP BY scenario_tag,abtest_group
)

INSERT OVERWRITE TABLE ${schema}.dws_sr_data_warehouse_ci_exp_scenario_level_general_1d
PARTITION (
    content = 'livestream',
    grass_region = ${grass_region},
    local_date = ${local_date}
)
SELECT
    abtest_group,
    scenario_tag,
    card_imp_cnt,
    card_imp_uu,
    card_click_cnt,
    card_click_uu
FROM
   final_data

